"""Generate packages/contracts/marks_messages.schema.json and marks_messages.ts from the models of the marks-messages API (job DP part 2). Same scheme as the other contracts (`make contracts`; a test fails if
either file is stale). Committed early: the school's upload screen is built against it."""

from __future__ import annotations

import json
from typing import Any

from pydantic import BaseModel
from pydantic.json_schema import models_json_schema

from app.marksmessages import models as m
from app.packs.contracts import _ts_type

HEADER = (
    "// GENERATED by `make contracts` from services/ai-api/app/marksmessages/models.py. Do not edit.\n"
    "// Marks and report messages to guardians from a file that is NEVER stored. The preview and the send answer with counts and closed codes; the log keeps the guardian, the time, the template id and the status only.\n"
)
RESPONSES: list[type[BaseModel]] = [m.TemplatesOut, m.PreviewOut, m.SendOut, m.BatchesOut, m.BatchOut]
REQUESTS: list[type[BaseModel]] = []  # the request is the raw file plus query parameters (see routes.py)


def build_schema() -> dict[str, Any]:
    _, defs = models_json_schema(
        [(model, "serialization") for model in RESPONSES] + [(model, "validation") for model in REQUESTS], ref_template="#/$defs/{model}"
    )
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "marks_messages.schema.json",
        "title": "Marks and report messages to guardians (job DP)",
        "description": "Generated from services/ai-api/app/marksmessages/models.py by `make contracts`.",
        "$defs": dict(sorted(defs.get("$defs", {}).items())),
    }


def schema_text() -> str:
    return json.dumps(build_schema(), indent=2, sort_keys=False) + "\n"


def ts_text() -> str:
    defs = build_schema()["$defs"]
    lines = [HEADER]
    for name, node in defs.items():
        ts_name = name.replace("_", "")
        if "enum" in node:
            lines.append(f"export type {ts_name} = {_ts_type(node)};\n")
            continue
        props = node.get("properties", {})
        required = set(node.get("required", []))
        body = []
        for prop, spec in props.items():
            optional = "" if prop in required else "?"
            body.append(f"  {prop}{optional}: {_ts_type(spec)};")
        lines.append(f"export interface {ts_name} {{\n" + "\n".join(body) + "\n}\n")
    return "\n".join(lines)
